import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"Sheet","description":"","frontmatter":{},"headers":[],"relativePath":"components/sheet.md","filePath":"components/sheet.md"}'),h={name:"components/sheet.md"};function s(r,e,n,l,c,i){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="sheet" tabindex="-1">Sheet <a class="header-anchor" href="#sheet" aria-label="Permalink to &quot;Sheet&quot;">​</a></h1><p>Sheet is a panel that comes up from the bottom of a narrow screen.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a panel that sits beside the stage on a wide screen, such as the details of a selection, when the screen is too narrow. The user chooses how much of the screen it takes.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>stage</code></td><td><code>half</code></td><td>The height: <code>peek</code>, <code>half</code> or <code>full</code> (bindable)</td></tr><tr><td><code>stages</code></td><td>all three</td><td>The heights offered, lowest first</td></tr><tr><td><code>onstage</code></td><td></td><td>Called when the height changes</td></tr><tr><td><code>closable</code></td><td><code>false</code></td><td>Below the lowest height, it closes</td></tr><tr><td><code>onclose</code></td><td></td><td>Called when it closes</td></tr><tr><td><code>pane</code></td><td><code>false</code></td><td>The content is a panel with its own head</td></tr><tr><td><code>label</code></td><td></td><td>The accessible name of the sheet</td></tr><tr><td><code>name</code></td><td></td><td>Tells several sheets apart (<code>data-sheet</code>)</td></tr><tr><td><code>z</code></td><td></td><td>The stacking order; the sheet layer by default</td></tr><tr><td><code>head</code></td><td></td><td>The head, which does not shrink (a snippet)</td></tr><tr><td><code>foot</code></td><td></td><td>The foot, a Footer (a snippet)</td></tr><tr><td><code>children</code></td><td>required</td><td>The content, which scrolls</td></tr><tr><td><code>inline</code></td><td><code>false</code></td><td>In the flow, for documentation</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>It is placed absolutely at the bottom of its frame, which must be a positioned element, with the panel surface and a strong line along its top. The order inside is fixed: a handle gap-md high (a bar of two lines), the head, the content and the foot; only the content shrinks and scrolls, and it has no padding. <code>peek</code> is as high as the handle and the head, <code>half</code> is the content&#39;s height up to half the frame (a taller content scrolls there, inside the panel with <code>pane</code>, through a wrapper of the application as tall as its place too) and <code>full</code> all of the frame. A press on the handle steps up through the heights and returns to the lowest; ArrowUp and ArrowDown on the handle step up and down; a drag follows the pointer and snaps to the nearest height on release. A drag that ends above the height it started from never snaps to a lower one, nor one that ends below it to a higher one, and the click that ends a drag does not step. With <code>closable</code>, a drag well below the lowest height, or ArrowDown there, closes it. The handle&#39;s name is the <code>sheetHeight</code> message.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/sheet/" title="Sheet" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/sheet/" target="_blank" rel="noopener">Sheet</a></figcaption></figure>',10)])])}const m=t(h,[["render",s]]);export{f as __pageData,m as default};
